<?php get_header(); ?><main id="main-content" class="site-main container section-space"><header class="page-header"><p class="eyebrow"><?php esc_html_e( 'Search', 'meridian-news' ); ?></p><h1><?php printf( esc_html__( 'Results for “%s”', 'meridian-news' ), esc_html( get_search_query() ) ); ?></h1><?php if ( have_posts() ) { ?><p><?php printf( esc_html( _n( '%s result found', '%s results found', (int) $wp_query->found_posts, 'meridian-news' ) ), number_format_i18n( $wp_query->found_posts ) ); ?></p><?php } ?></header><?php if ( have_posts() ) : ?><div class="card-grid"><?php while ( have_posts() ) : the_post(); get_template_part( 'template-parts/content', 'card' ); endwhile; ?></div><?php meridian_news_pagination(); else : ?><div class="empty-state"><h2><?php esc_html_e( 'No matching stories', 'meridian-news' ); ?></h2><p><?php esc_html_e( 'Try a broader search term.', 'meridian-news' ); ?></p><?php get_search_form(); ?></div><?php endif; ?></main><?php get_footer(); ?>
